import itertools

def solve(instance):
    try:
        # Parse jobs
        jobs_raw = instance.get('jobs', [])
        if not jobs_raw:
            return {"order": [], "total_tardiness": 0.0}

        # Convert to list of tuples/dicts for easier handling
        jobs = []
        for j in jobs_raw:
            jobs.append({
                'id': j.get('id'),
                'processing_time': j.get('processing_time', 0),
                'due_date': j.get('due_date', 0)
            })

        n = len(jobs)
        min_total_tardiness = float('inf')
        best_sequence = None

        # Since n=5, 5! = 120 permutations is very small.
        # We can brute force all permutations to find the global optimum.
        indices = list(range(n))

        for perm in itertools.permutations(indices):
            current_time = 0
            total_tardiness = 0

            for idx in perm:
                job = jobs[idx]
                current_time += job['processing_time']
                tardiness = max(0, current_time - job['due_date'])
                total_tardiness += tardiness

            if total_tardiness < min_total_tardiness:
                min_total_tardiness = total_tardiness
                best_sequence = [jobs[idx]['id'] for idx in perm]

        return {
            "order": best_sequence,
            "total_tardiness": min_total_tardiness
        }

    except Exception as e:
        # Fallback in case of any error
        return {"order": [], "total_tardiness": 0.0}

